window.addEventListener('keydown', (event) => {
  if (event.repeat) {
    keys.add(event.code);
    return;
  }
  if (event.code === 'Space') event.preventDefault();
  keys.add(event.code);
  if (event.code === 'Space') jumpQueued = true;
