  const dir = new THREE.Vector3(Math.sin(orbit.yaw), 0.08, Math.cos(orbit.yaw)).normalize();
  tracerFrom.copy(eye);
  tracerTo.copy(eye).addScaledVector(dir, 45);
  tracerGeometry.setFromPoints([tracerFrom, tracerTo]);
  tracerMaterial.opacity = 0.9;
