function segmentBox(ox, oy, oz, dx, dy, dz, b, pad) {
  const minX = b.x0 - pad;
  const maxX = b.x1 + pad;
  const minY = -pad;
  const maxY = b.top + pad;
  const minZ = b.z0 - pad;
  const maxZ = b.z1 + pad;

  let t0 = 0;
  let t1 = 1;

